import re
import csv
import io
import xml.etree.ElementTree as ET


def _clean_text(text):
    if text is None:
        return ""
    text = text.replace("\u2003", " ")
    text = text.replace("\u2032", "'")
    text = text.replace("\u2020", "")
    text = text.replace("\u2021", "")
    text = re.sub(r"\s+", " ", text)
    return text.strip()


def _get_row_cells(row_elem):
    cells = []
    for entry in row_elem.findall("entry"):
        txt = "".join(entry.itertext())
        cells.append(_clean_text(txt))
    return cells


def _is_spacer_row(cells):
    if not cells:
        return True
    joined = "".join(cells).strip()
    if joined == "":
        return True
    return False


def _to_nm(value, unit):
    try:
        v = float(value)
    except ValueError:
        return None
    unit = unit.lower().strip()
    if unit in ("nm",):
        return _fmt_num(v)
    if unit in ("um", "\u00b5m", "micromolar"):
        return _fmt_num(v * 1000)
    if unit in ("mm",):
        return _fmt_num(v * 1000000)
    return _fmt_num(v)


def _fmt_num(v):
    if v == int(v):
        return str(int(v))
    return str(v)


def _extract_compound_id(cell):
    if not cell:
        return None
    m = re.search(r"(\d{4,7})", cell)
    if m:
        return m.group(1)
    return None


def _looks_like_sequence(cell):
    if not cell:
        return False
    c = cell.strip().upper()
    letters = re.sub(r"[^ATGC]", "", c)
    return len(letters) >= 8


def _validate_sequence(cell):
    if not cell:
        return "NA"
    c = cell.strip().upper()
    letters = re.sub(r"[^ATGC]", "", c)
    if len(letters) >= 8:
        return c
    return "NA"


def _is_number(s):
    try:
        float(s)
        return True
    except (ValueError, TypeError):
        return False


def _parse_dose_header(cells_header_rows, ncols):
    # Try to find concentration + unit info per column
    # cells_header_rows: list of rows (each a list of cells), possibly ragged/shifted
    # Returns dict: col_index -> concentration_in_nM (string) or None
    col_conc = {}
    unit_pattern = re.compile(r"^(nM|uM|\u00b5M|mM)$", re.IGNORECASE)
    num_unit_pattern = re.compile(r"^([0-9]*\.?[0-9]+)\s*(nM|uM|\u00b5M|mM)$", re.IGNORECASE)

    # Build aligned rows: right-align against ncols (data row length)
    aligned_rows = []
    for row in cells_header_rows:
        offset = ncols - len(row)
        if offset < 0:
            offset = 0
        aligned = [None] * ncols
        for i, val in enumerate(row):
            idx = i + offset
            if idx < ncols:
                aligned[idx] = val
        aligned_rows.append(aligned)

    # look for a row with plain numbers, and next row with units
    for r_idx, row in enumerate(aligned_rows):
        for c_idx, val in enumerate(row):
            if val is None:
                continue
            m = num_unit_pattern.match(val.strip())
            if m:
                col_conc[c_idx] = _to_nm(m.group(1), m.group(2))
                continue
            if _is_number(val.strip()):
                # look for unit in subsequent rows same column
                for r2 in range(r_idx + 1, len(aligned_rows)):
                    unit_val = aligned_rows[r2][c_idx] if c_idx < len(aligned_rows[r2]) else None
                    if unit_val and unit_pattern.match(unit_val.strip()):
                        col_conc[c_idx] = _to_nm(val.strip(), unit_val.strip())
                        break
    return col_conc


def _extract_all_rows_from_table(table_elem):
    all_rows = []
    for tgroup in table_elem.findall("tgroup"):
        tbody = tgroup.find("tbody")
        if tbody is None:
            continue
        for row in tbody.findall("row"):
            cells = _get_row_cells(row)
            all_rows.append(cells)
    return all_rows


def _find_header_and_data(rows):
    # Determine max column count from rows that look like data (numeric compound id present)
    data_row_indices = []
    for i, row in enumerate(rows):
        if _is_spacer_row(row):
            continue
        if len(row) >= 2 and re.match(r"^\d{4,7}", row[0].strip()):
            data_row_indices.append(i)
    return data_row_indices


def xml_to_csv(xml_str: str) -> str:
    xml_str = xml_str.replace("&#x2003;", " ")

    # Try to parse XML; wrap in root if needed and fix unclosed tags
    try:
        # attempt direct parse by wrapping fragments
        wrapped = "<root>" + xml_str + "</root>"
        root = ET.fromstring(wrapped)
    except ET.ParseError:
        # try to fix common issues - truncated/unclosed tags - best effort
        cleaned = re.sub(r"<!--.*?-->", "", xml_str, flags=re.DOTALL)
        # remove any trailing incomplete tag fragments
        cleaned = re.sub(r"<[^>]*$", "", cleaned)
        try:
            wrapped = "<root>" + cleaned + "</root>"
            root = ET.fromstring(wrapped)
        except ET.ParseError:
            root = None

    output_rows = []

    if root is None:
        return _build_csv(output_rows)

    tables = root.findall(".//tables")
    if not tables:
        tables = root.findall(".//table")

    for tables_elem in tables:
        table_elems = tables_elem.findall(".//table") if tables_elem.tag == "tables" else [tables_elem]
        if not table_elems:
            table_elems = [tables_elem]

        # gather all rows across all tgroups/tables within this tables block
        all_rows = []
        for t in table_elems:
            all_rows.extend(_extract_all_rows_from_table(t))

        if not all_rows:
            continue

        # find caption text for %UTC detection
        caption_text = " ".join([" ".join(r) for r in all_rows[:8]]).lower()
        is_utc = ("% utc" in caption_text or "utc" in caption_text or "% control" in caption_text or "control)" in caption_text) and "inhibit" not in caption_text

        data_indices = _find_header_and_data(all_rows)
        if not data_indices:
            continue

        ncols = max(len(all_rows[i]) for i in data_indices)

        header_rows = []
        first_data_idx = data_indices[0]
        for i in range(first_data_idx):
            row = all_rows[i]
            if _is_spacer_row(row):
                continue
            joined = " ".join(row).strip()
            if joined.upper().startswith("TABLE"):
                continue
            header_rows.append(row)

        # determine column roles by scanning header rows text
        header_flat_cols = {}
        offset_rows = []
        for row in header_rows:
            offset = ncols - len(row)
            if offset < 0:
                offset = 0
            aligned = [None] * ncols
            for i, val in enumerate(row):
                idx = i + offset
                if idx < ncols:
                    aligned[idx] = val
            offset_rows.append(aligned)

        col_text = ["" for _ in range(ncols)]
        for aligned in offset_rows:
            for idx, val in enumerate(aligned):
                if val:
                    col_text[idx] = (col_text[idx] + " " + val).strip()

        seq_col = None
        sugar_col = None
        backbone_col = None
        inhib_col = None
        utc_col = None
        compound_col = 0

        for idx, txt in enumerate(col_text):
            low = txt.lower()
            if "sequence" in low:
                seq_col = idx
            if "sugar" in low or "motif" in low and "sugar" in low:
                sugar_col = idx
            if "linkage" in low or "backbone" in low:
                backbone_col = idx
            if "inhibit" in low:
                inhib_col = idx
            if "utc" in low or "control" in low:
                utc_col = idx
            if "compound" in low or "isis" in low:
                compound_col = idx

        # detect dose-response header (numeric concentrations across columns)
        col_conc = _parse_dose_header(header_rows, ncols)
        is_dose_response = len(col_conc) >= 2

        for di in data_indices:
            row = all_rows[di]
            if len(row) < ncols:
                row = row + [""] * (ncols - len(row))

            compound_raw = row[compound_col]
            compound_id = _extract_compound_id(compound_raw)
            if not compound_id:
                continue

            sequence = "NA"
            if seq_col is not None and seq_col < len(row):
                sequence = _validate_sequence(row[seq_col])

            sugar_motif = "NA"
            if sugar_col is not None and sugar_col < len(row):
                val = row[sugar_col].strip()
                sugar_motif = val if val else "NA"

            backbone_motif = "NA"
            if backbone_col is not None and backbone_col < len(row):
                val = row[backbone_col].strip()
                backbone_motif = val if val else "NA"

            if is_dose_response:
                for cidx, conc in col_conc.items():
                    if cidx >= len(row):
                        continue
                    val = row[cidx].strip()
                    if val == "" or not _is_number(val):
                        continue
                    if is_utc:
                        try:
                            pct = 100 - float(val)
                        except ValueError:
                            continue
                        note = "converted from %UTC"
                        pct_str = _fmt_num(pct)
                    else:
                        pct_str = val
                        note = "inhibition"
                    output_rows.append([
                        compound_id, sequence, sugar_motif, backbone_motif,
                        conc if conc is not None else "NA", pct_str, note
                    ])
            else:
                pct_val = None
                note = None
                if inhib_col is not None and inhib_col < len(row) and row[inhib_col].strip() != "":
                    v = row[inhib_col].strip()
                    if _is_number(v):
                        pct_val = v
                        note = "inhibition"
                elif utc_col is not None and utc_col < len(row) and row[utc_col].strip() != "":
                    v = row[utc_col].strip()
                    if _is_number(v):
                        pct_val = _fmt_num(100 - float(v))
                        note = "converted from %UTC"

                if pct_val is None:
                    # try last numeric-looking column as fallback
                    for idx in range(len(row) - 1, -1, -1):
                        v = row[idx].strip()
                        if idx == compound_col:
                            continue
                        if _is_number(v):
                            if is_utc:
                                pct_val = _fmt_num(100 - float(v))
                                note = "converted from %UTC"
                            else:
                                pct_val = v
                                note = "inhibition"
                            break

                if pct_val is None:
                    continue

                output_rows.append([
                    compound_id, sequence, sugar_motif, backbone_motif,
                    "NA", pct_val, note
                ])

    return _build_csv(output_rows)


def _build_csv(rows):
    output = io.StringIO()
    writer = csv.writer(output, lineterminator="\n")
    writer.writerow([
        "Compound ID", "sequence", "sugar_motif", "backbone_motif",
        "dosage_nm", "Inhibition_pct", "measurement_note"
    ])

    for row in rows:
        compound_id = row[0]
        if not re.match(r"^\d{4,7}$", compound_id):
            continue
        if not _is_number(str(row[5])):
            continue
        writer.writerow(row)

    return output.getvalue()
